INSERT INTO app.procedures (code, category, name_ko, name_en, name_zh, name_ja, synonyms, duration_min, downtime_days, description_ko, description_en) VALUES
('JAW_BOTOX', 'SKIN', '사각턱 보톡스', 'Jaw (Masseter) Botox', '瘦脸针', 'エラボトックス', ARRAY['사각턱 보톡스','턱보톡스','masseter botox','jaw botox','瘦脸针','エラボトックス']::text[], 15, 0, '저작근에 보툴리눔 톡신을 주입해 턱선을 갸름하게 보이도록 돕는 시술입니다.', 'Botulinum toxin injected into the masseter muscles to help slim the appearance of the lower face.'),
('FOREHEAD_BOTOX', 'SKIN', '이마 보톡스', 'Forehead Botox', '额头肉毒素', '額ボトックス', ARRAY['이마 주름 보톡스','forehead botox','forehead wrinkle botox','抬头纹肉毒','額のしわボトックス']::text[], 10, 0, '이마 근육의 움직임을 줄여 가로 주름을 완화하는 시술입니다.', 'Botulinum toxin to soften horizontal forehead lines by relaxing the frontalis muscle.'),
('LIP_FILLER', 'SKIN', '입술 필러', 'Lip Filler', '嘴唇玻尿酸', '唇ヒアルロン酸', ARRAY['입술필러','lip filler','lip augmentation','丰唇','唇フィラー']::text[], 20, 1, '히알루론산 필러로 입술 볼륨과 라인을 보완하는 시술입니다.', 'Hyaluronic acid filler to add volume and definition to the lips.'),
('NOSE_FILLER', 'SKIN', '코 필러', 'Nose Filler', '鼻子玻尿酸', '鼻ヒアルロン酸', ARRAY['코필러','nose filler','non-surgical rhinoplasty','隆鼻针','鼻フィラー']::text[], 20, 1, '필러로 콧대와 코끝 라인을 비수술적으로 보완하는 시술입니다.', 'Non-surgical reshaping of the nasal bridge or tip using hyaluronic acid filler.'),
('REJURAN', 'SKIN', '리쥬란 힐러', 'Rejuran Healer', '丽珠兰', 'リジュラン', ARRAY['리쥬란','rejuran','skin booster','丽珠兰','婴儿针','リジュランヒーラー']::text[], 40, 2, '폴리뉴클레오타이드 성분을 피부에 주입해 피부 컨디션 개선을 돕는 스킨부스터입니다.', 'A polynucleotide-based skin-booster injection aimed at improving skin texture and condition.'),
('ULTHERAPY', 'SKIN', '울쎄라', 'Ultherapy', '超声刀', 'ウルセラ', ARRAY['울쎄라 리프팅','ultherapy','HIFU lifting','超声刀','ウルセラリフト']::text[], 60, 0, '고강도 집속 초음파로 피부 깊은 층을 자극해 리프팅 효과를 기대하는 시술입니다.', 'Microfocused ultrasound treatment targeting deeper skin layers for a lifting effect.'),
('THERMAGE', 'SKIN', '써마지', 'Thermage FLX', '热玛吉', 'サーマクール', ARRAY['써마지FLX','thermage','RF skin tightening','热玛吉','サーマクールFLX']::text[], 60, 0, '고주파 에너지로 피부 탄력 개선을 돕는 시술입니다.', 'Monopolar radiofrequency treatment intended to tighten and firm the skin.'),
('SHURINK', 'SKIN', '슈링크', 'Shurink (HIFU)', '舒铃超声提拉', 'シュリンク', ARRAY['슈링크 유니버스','shurink','HIFU','舒铃','シュリンク']::text[], 30, 0, '집속 초음파 장비로 비교적 짧은 시간에 리프팅을 기대하는 시술입니다.', 'A focused-ultrasound lifting treatment with relatively short treatment time.'),
('PICO_TONING', 'SKIN', '피코토닝', 'Pico Toning', '皮秒激光', 'ピコトーニング', ARRAY['피코 레이저','pico toning','pico laser','皮秒','ピコレーザー']::text[], 20, 0, '피코초 레이저로 색소와 피부톤 개선을 돕는 시술입니다.', 'Picosecond laser toning aimed at pigmentation and uneven skin tone.'),
('LASER_HAIR_REMOVAL', 'SKIN', '레이저 제모', 'Laser Hair Removal', '激光脱毛', 'レーザー脱毛', ARRAY['제모','laser hair removal','hair removal','激光脱毛','医療脱毛']::text[], 30, 0, '레이저로 모낭을 표적해 체모를 줄이는 시술로 여러 회차가 필요합니다.', 'Laser treatment targeting hair follicles to reduce hair growth; multiple sessions are usually needed.'),
('DOUBLE_EYELID_NONINCISION', 'SURGERY', '매몰법 쌍꺼풀', 'Non-incisional Double Eyelid', '埋线双眼皮', '埋没法二重', ARRAY['매몰법','비절개 쌍꺼풀','non-incisional double eyelid','suture double eyelid','埋线双眼皮','埋没法']::text[], 40, 5, '피부를 절개하지 않고 봉합사로 쌍꺼풀 라인을 만드는 수술입니다.', 'Creates a double eyelid crease with sutures, without a skin incision.'),
('DOUBLE_EYELID_INCISION', 'SURGERY', '절개법 쌍꺼풀', 'Incisional Double Eyelid', '全切双眼皮', '切開法二重', ARRAY['절개 쌍꺼풀','incisional double eyelid','incisional blepharoplasty','全切双眼皮','切開法']::text[], 90, 10, '눈꺼풀 피부를 절개해 지방·피부를 정리하고 쌍꺼풀 라인을 만드는 수술입니다.', 'Creates a crease through an eyelid incision, often with removal of excess skin or fat.'),
('PTOSIS_CORRECTION', 'SURGERY', '눈매교정', 'Ptosis Correction', '眼睑下垂矫正', '眼瞼下垂手術', ARRAY['눈매 교정술','ptosis correction','eye opening surgery','眼睑下垂矫正','眼瞼下垂']::text[], 90, 10, '눈을 뜨는 근육의 힘을 보완해 또렷한 눈매를 만드는 수술입니다.', 'Adjusts the eyelid-lifting muscle to correct drooping lids and open the eyes.'),
('RHINOPLASTY', 'SURGERY', '코성형', 'Rhinoplasty', '隆鼻手术', '鼻整形', ARRAY['코 수술','rhinoplasty','nose job','隆鼻','鼻整形']::text[], 150, 10, '보형물이나 자가 연골을 이용해 코의 모양을 개선하는 수술입니다.', 'Surgical reshaping of the nose using implants and/or the patient''s own cartilage.'),
('FACIAL_CONTOURING', 'SURGERY', '안면윤곽', 'Facial Contouring', '面部轮廓手术', '輪郭形成', ARRAY['윤곽 수술','광대축소','facial contouring','V-line surgery','削骨','輪郭手術']::text[], 240, 21, '광대·사각턱·턱끝 뼈를 다듬어 얼굴 윤곽을 바꾸는 수술입니다.', 'Bone surgery on the cheekbones, jaw angle and/or chin to change the facial outline.'),
('FAT_GRAFTING', 'SURGERY', '지방이식', 'Fat Grafting', '自体脂肪移植', '脂肪注入', ARRAY['얼굴 지방이식','fat grafting','fat transfer','脂肪填充','脂肪注入']::text[], 120, 7, '자신의 지방을 채취·정제해 볼륨이 필요한 부위에 이식하는 수술입니다.', 'Harvests and purifies the patient''s own fat and injects it where volume is desired.'),
('LIPOSUCTION', 'SURGERY', '지방흡입', 'Liposuction', '吸脂', '脂肪吸引', ARRAY['지방 흡입술','liposuction','lipo','抽脂','脂肪吸引']::text[], 150, 7, '캐뉼라로 피하지방을 제거해 체형을 다듬는 수술입니다.', 'Removes subcutaneous fat with a cannula to contour body areas.'),
('BREAST_AUGMENTATION', 'SURGERY', '가슴성형', 'Breast Augmentation', '隆胸', '豊胸手術', ARRAY['가슴 확대','breast augmentation','breast implants','隆胸','豊胸']::text[], 150, 14, '보형물 등을 이용해 가슴 볼륨을 보완하는 수술입니다.', 'Increases breast volume, typically with implants.');
