(1, 3, 1, 7, '14b46725-af1f-421e-9e26-b61de7a4e064'::uuid, 'ACTIVE', 'zh', '{"concerns": ["恢复期", "回国航班时间", "价格是否含税"], "language": "zh", "preferred_areas": ["GANGNAM", "MYEONGDONG"], "preferred_dates": ["2026-10-23", "2026-10-29"], "procedure_code": "DOUBLE_EYELID_NONINCISION", "procedure_name": "埋线双眼皮"}'::jsonb, '{"concerns": ["회복 기간", "귀국 비행 일정", "부가세 포함 여부"], "language": "zh", "preferred_areas": ["강남", "명동"], "preferred_dates": ["2026-10-23", "2026-10-29"], "procedure_code": "DOUBLE_EYELID_NONINCISION", "procedure_name": "매몰법 쌍꺼풀"}'::jsonb, '2026-10-22T09:04:00+09:00', '2026-10-22T09:05:00+09:00', NULL),
(2, 5, 1, NULL, 'c531e074-dbd1-492c-9ca3-2e67670d0f86'::uuid, 'WAITING', 'ja', '{"concerns": ["効果の持続期間", "日本語の通訳"], "language": "ja", "preferred_areas": ["GANGNAM"], "preferred_dates": ["2026-10-23", "2026-10-23"], "procedure_code": "JAW_BOTOX", "procedure_name": "エラボトックス"}'::jsonb, '{"concerns": ["효과 지속 기간", "일본어 통역"], "language": "ja", "preferred_areas": ["강남"], "preferred_dates": ["2026-10-23", "2026-10-23"], "procedure_code": "JAW_BOTOX", "procedure_name": "사각턱 보톡스"}'::jsonb, '2026-10-22T09:39:00+09:00', '2026-10-22T09:40:00+09:00', NULL);
INSERT INTO app.chat_messages (id, consultation_id, sender_id, sender_role, original_text, original_lang, translated_text, translated_lang, translation_status, flags, created_at) VALUES
(1, 1, 3, 'CUSTOMER', '您好，我想咨询一下埋线双眼皮。下周可以预约吗？', 'zh', '안녕하세요, 매몰법 쌍꺼풀 상담을 받고 싶어요. 다음 주에 예약이 가능할까요?', 'ko', 'DONE', '{"glossary_hits": ["埋线双眼皮=매몰법"]}'::jsonb, '2026-10-22T09:06:00+09:00'),
(2, 1, 7, 'COUNSELOR', '안녕하세요! 네, 다음 주 화요일과 목요일 오후에 상담 가능한 시간이 있습니다. 원하시는 날짜가 있으신가요?', 'ko', '您好！是的，下周二和周四下午有可以面诊的时间。您有希望的日期吗？', 'zh', 'DONE', '{}'::jsonb, '2026-10-22T09:08:00+09:00'),
(3, 1, 3, 'CUSTOMER', '周四下午比较好。手术后多久可以坐飞机回国？', 'zh', '목요일 오후가 좋아요. 수술 후 얼마나 지나야 비행기를 타고 귀국할 수 있나요?', 'ko', 'DONE', '{}'::jsonb, '2026-10-22T09:10:00+09:00'),
(4, 1, 7, 'COUNSELOR', '개인차가 있지만 매몰법은 보통 수술 후 며칠 내 비행하는 경우가 많습니다. 정확한 일정은 원장님 진료 시 확인해 주세요.', 'ko', '虽然因人而异，但埋线法通常在术后几天内乘坐飞机的情况较多。具体日程请在院长面诊时确认。', 'zh', 'DONE', '{"glossary_hits": ["매몰법=埋线法"], "medical_content": true}'::jsonb, '2026-10-22T09:13:00+09:00'),
(5, 1, 3, 'CUSTOMER', '好的。价格大概是多少？包含增值税吗？', 'zh', '알겠습니다. 가격은 대략 얼마인가요? 부가세 포함인가요?', 'ko', 'DONE', '{"glossary_hits": ["增值税=부가세"]}'::jsonb, '2026-10-22T09:15:00+09:00'),
(6, 1, 7, 'COUNSELOR', '매몰법 양쪽 기준 860,000원부터이며, 최종 금액은 상담 후 확정됩니다. 예약 요청을 남겨주시면 병원 확인 후 확정됩니다.', 'ko', '埋线法双眼起价860,000韩元，最终价格将在面诊后确定。提交预约申请后，经医院确认即可确定预约。', 'zh', 'DONE', '{"price_quote": true}'::jsonb, '2026-10-22T09:18:00+09:00');
